public class Runner {
    record Case(String label, int[] input, int expected) {}

    public static void main(String[] args) {
        Case[] cases = new Case[]{
            new Case("[3, 1, 5, 2, 4]", new int[]{3, 1, 5, 2, 4}, 5),
            new Case("[10]", new int[]{10}, 10),
            new Case("[-3, -1, -5, -2]", new int[]{-3, -1, -5, -2}, -1),
            new Case("[-100, -50, -1, -200]", new int[]{-100, -50, -1, -200}, -1)
        };
        for (Case c : cases) {
            try {
                int actual = Solution.findMax(c.input);
                if (actual == c.expected) {
                    System.out.println("PASS\t" + c.label);
                } else {
                    System.out.println("FAIL\t" + c.label + "\t" + c.expected + "\t" + actual);
                }
            } catch (Throwable t) {
                System.out.println("ERROR\t" + c.label + "\t" + t.getClass().getSimpleName() + ": " + t.getMessage());
            }
        }
    }
}
